// 新计划只引用本人实际来源；当前/归档均用原复评时刻，不以今日钟倒填未来办理。
#include "political_subordinate_appointment_director.hpp"
#include <set>
namespace hanmo::resident {
Status validate_political_subordinate_appointment_director(const DirectorCatalog& catalog,const DirectorState& director,const PoliticalSubordinateAppointmentContext* x){
 const auto& policies=catalog.dynamic_subjects?catalog.policies:catalog.subjects;
 if(x){if(!x->intents)return common_failure("PoliticalSubordinateIntentProfileRequired");auto valid=validate_political_subordinate_appointment_intents(*x->intents,x->common_catalog,x->politics_catalog,x->organization_catalog,x->heads,x->catalog,x->career);if(!valid.ok)return valid;for(const auto& row:x->intents->intents.rows()){const auto& i=row.second;const auto& p=*x->catalog.policies.find(i.appointment_policy_id);const auto& j=*x->politics_catalog.jurisdictions.find(p.jurisdiction_id);for(const auto& role:std::vector<std::pair<StableId,StableId>>{{i.issuer_actor_id,i.issuer_director_policy_id},{i.candidate_actor_id,i.candidate_director_policy_id}}){const auto* selected=policies.find(role.second);if(!selected||!selected->political_career||selected->organization_id!=j.political_organization_id||std::find(selected->templates.begin(),selected->templates.end(),DirectorTemplate::political_career)==selected->templates.end()||x->career(role.second)!=&*selected->political_career||(!catalog.dynamic_subjects&&role.first!=role.second))return common_failure("PoliticalSubordinateDirectorPolicyMismatch",i.id);}}}
 const auto plans=[&](const OrderedTable<FinitePlan>& table,bool archived)->Status{for(const auto& row:table.rows()){const auto& plan=row.second;if(plan.template_id!=political_subordinate_appointment_template)continue;if(!x||!x->intents||plan.subject.kind!=SubjectKind::actor||plan.subject.id.empty()||!plan.commitment_ids.empty()||plan.livelihood||plan.pending_life_action_id||plan.last_life_fact_id||(plan.phase!=PlanPhase::waiting&&plan.phase!=PlanPhase::delivering&&plan.phase!=PlanPhase::completed))return common_failure("PoliticalSubordinateDirectorPlanMismatch",row.first);const StableId selected=catalog.dynamic_subjects?plan.policy_id:plan.subject.id;const auto* policy=policies.find(selected);if(!policy||!policy->political_career||std::find(policy->templates.begin(),policy->templates.end(),DirectorTemplate::political_career)==policy->templates.end())return common_failure("PoliticalSubordinateDirectorPolicyMismatch",row.first);
  const Integer delay=std::max(catalog.retry_delay_ticks,catalog.review_interval_ticks);if(delay<1||plan.next_review_tick<delay)return common_failure("PoliticalSubordinateReviewRequired",row.first);const Integer observed=plan.next_review_tick-delay;if(observed>x->common.tick())return common_failure("PoliticalSubordinateReviewRequired",row.first);if(!archived){const auto* schedule=director.schedules.find(plan.subject.id);if(!schedule||schedule->last_decision_tick!=observed||schedule->next_tick!=plan.next_review_tick)return common_failure("PoliticalSubordinateReviewRequired",row.first);}
  const PoliticalSubordinateAppointmentOffer* offer=x->state.offers.find(plan.goal_ref);const auto* answer=x->state.answers.find(plan.goal_ref);const auto* arrival=x->state.arrivals.find(plan.goal_ref);Integer source_tick=-1;StableId own_actor;if(offer){source_tick=offer->tick;own_actor=offer->issuer_actor_id;}else if(answer){offer=x->state.offers.find(answer->offer_fact_id);source_tick=answer->tick;own_actor=answer->actor_id;}else if(arrival){const auto* accepted=x->state.answers.find(arrival->acceptance_fact_id);offer=accepted?x->state.offers.find(accepted->offer_fact_id):nullptr;source_tick=arrival->tick;own_actor=arrival->actor_id;}
  const PoliticalSubordinateAppointmentIntent* intent=nullptr;for(const auto& i:x->intents->intents.rows()){const bool person=(plan.subject.id==i.second.issuer_actor_id&&selected==i.second.issuer_director_policy_id)||(plan.subject.id==i.second.candidate_actor_id&&selected==i.second.candidate_director_policy_id);if(!person)continue;if(offer){if(offer->policy_id==i.second.appointment_policy_id&&offer->issuer_actor_id==i.second.issuer_actor_id&&offer->candidate_actor_id==i.second.candidate_actor_id)intent=&i.second;}else if(plan.goal_ref==i.first)intent=&i.second;}if(!intent)return common_failure("PoliticalSubordinatePlanIntentRequired",row.first);
  if(offer){if(source_tick<0||source_tick>observed||(plan.subject.id!=offer->issuer_actor_id&&plan.subject.id!=offer->candidate_actor_id))return common_failure("PoliticalSubordinateKnownPlanSourceRequired",row.first);}else if(plan.subject.id!=intent->issuer_actor_id||plan.phase==PlanPhase::completed)return common_failure("PoliticalSubordinateKnownPlanSourceRequired",row.first);
  if(plan.phase==PlanPhase::completed){if(plan.current_action_id||own_actor!=plan.subject.id||(!arrival&&!(answer&&!answer->accepted)&&!x->state.offers.find(plan.goal_ref)))return common_failure("PoliticalSubordinateCompletedSourceRequired",row.first);}
  else if(plan.phase==PlanPhase::waiting&&plan.current_action_id)return common_failure("PoliticalSubordinateUnexpectedPlanAction",row.first);
 }return common_success();};auto checked=plans(director.plans,false);return checked.ok?plans(director.archived_plans,true):checked;
}
}
